    for r in range(h):
        run = 0
        for c in range(w):
            run += (grid[r][c] != bg)
            pnon[r + 1][c + 1] = pnon[r][c + 1] + run

    def count(p, r0, c0, r1, c1):
        return p[r1][c1] - p[r0][c1] - p[r1][c0] + p[r0][c0]

    candidates = {color: [] for color in colors}
    for r0 in range(h - 1):
